import java.io.*;
import java.util.*;

public class Main {
    static ArrayList<Integer>[] adj;
    static ArrayList<Integer>[] adjr;
    static int[] mark;
    static int[] ans;
    static int[] st;
    static int n, m;

    static void dfs1(int x) {
        mark[x] = 1;
        ans[x]++;
        for (int u : adj[x]) {
            if (mark[u] == 0) {
                dfs1(u);
            }
        }
    }

    static void dfs2(int x) {
        mark[x] = 1;
        ans[x]++;
        if (st[x] == 1) return;
        for (int u : adjr[x]) {
            if (mark[u] == 0) {
                dfs2(u);
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer stk = new StringTokenizer(br.readLine());
        n = Integer.parseInt(stk.nextToken());
        m = Integer.parseInt(stk.nextToken());

        adj = new ArrayList[n];
        adjr = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new ArrayList<>();
            adjr[i] = new ArrayList<>();
        }

        mark = new int[n];
        ans = new int[n];
        st = new int[n];

        stk = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) {
            st[i] = Integer.parseInt(stk.nextToken());
        }

        for (int i = 0; i < m; i++) {
            stk = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(stk.nextToken()) - 1;
            int v = Integer.parseInt(stk.nextToken()) - 1;
            adj[u].add(v);
            adjr[v].add(u);
        }

        for (int i = 0; i < n; i++) {
            if (mark[i] == 0 && st[i] == 1) {
                dfs1(i);
            }
        }

        Arrays.fill(mark, 0);

        for (int i = 0; i < n; i++) {
            if (mark[i] == 0 && st[i] == 2) {
                dfs2(i);
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (ans[i] == 2) {
                sb.append(1);
            } else {
                sb.append(0);
            }
            sb.append('\n');
        }
        System.out.print(sb);
    }
}

