import java.io.*;
import java.util.*;

public class Main {
    static int n, m;
    static List<List<Integer>> adj, adjr;
    static int[] mark, ans, st;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer stk = new StringTokenizer(br.readLine());
        n = Integer.parseInt(stk.nextToken());
        m = Integer.parseInt(stk.nextToken());

        st = new int[n];
        stk = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) {
            st[i] = Integer.parseInt(stk.nextToken());
        }

        adj = new ArrayList<>(n);
        adjr = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
            adjr.add(new ArrayList<>());
        }

        for (int i = 0; i < m; i++) {
            stk = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(stk.nextToken()) - 1;
            int v = Integer.parseInt(stk.nextToken()) - 1;
            adj.get(u).add(v);
            adjr.get(v).add(u);
        }

        mark = new int[n];
        ans = new int[n];

        // DFS 1: from st==1 on forward graph
        for (int i = 0; i < n; i++) {
            if (mark[i] == 0 && st[i] == 1) {
