            }
        }

        // Reset mark
        Arrays.fill(mark, 0);

        // DFS 2: from st==2 on reverse graph
        for (int i = 0; i < n; i++) {
            if (mark[i] == 0 && st[i] == 2) {
                dfs2(i);
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (ans[i] == 2) sb.append(1);
            else sb.append(0);
            sb.append('\n');
        }
        System.out.print(sb);
    }

    static void dfs1(int start) {
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(start);
        while (!stack.isEmpty()) {
            int x = stack.pop();
            if (mark[x] == 1) continue;
            mark[x] = 1;
            ans[x]++;
            // if (st[x] == 2) continue; // commented out in original
            for (int u : adj.get(x)) {
                if (mark[u] == 0) {
                    stack.push(u);
                }
            }
        }
    }

    static void dfs2(int start) {
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(start);
        while (!stack.isEmpty()) {
            int x = stack.pop();
            if (mark[x] == 1) continue;
            mark[x] = 1;
            ans[x]++;
            if (st[x] == 1) continue; // stop condition
            for (int u : adjr.get(x)) {
                if (mark[u] == 0) {
                    stack.push(u);
                }
            }
        }
    }
}
